{/* RIGHT PANEL */}
<div style={{ width: 340, flexShrink: 0 }}>
  <h4>Details</h4>

  {selectedNgo ? (
    <div style={{ background: '#fff', padding: 12, borderRadius: 10 }}>
      <h5>{selectedNgo?.ngo?.name || "Unknown NGO"}</h5>
      <div style={{ fontSize: 13, color: '#666' }}>
        {selectedNgo?.ngo?.email || "No email available"}
      </div>

      <div style={{ marginTop: 10 }}>
        <strong>Events</strong>
        {selectedNgo?.events?.length > 0 ? (
          selectedNgo.events.map(ev => (
            <div key={ev.id} style={{ padding: 8, borderBottom: '1px solid #f0f0f0' }}>
              {ev.title}
            </div>
          ))
        ) : (
          <div>No events yet.</div>
        )}
      </div>

      <div style={{ marginTop: 10 }}>
        <strong>Recent Donations</strong>
        {selectedNgo?.donations?.length > 0 ? (
          selectedNgo.donations.slice(0, 6).map(d => (
            <div key={d.id} style={{ padding: 6 }}>
              {d.donor_name} — ₹{d.amount}
            </div>
          ))
        ) : (
          <div>No donations yet.</div>
        )}
      </div>
    </div>
  ) : (
    <div style={{
      background: '#fff', padding: 12, borderRadius: 10,
      display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center'
    }}>
      {/* Profile Icon */}
      <div style={{
        width: 60, height: 60, borderRadius: '50%',
        background: '#ddd', display: 'flex', alignItems: 'center', justifyContent: 'center',
        fontSize: 28, marginBottom: 10
      }}>
        {me?.name ? me.name.charAt(0).toUpperCase() : "?"}
      </div>

      <div style={{ fontWeight: 'bold', marginBottom: 4 }}>
        {me?.name || "No Name"}
      </div>
      <div style={{ fontSize: 13, color: '#666', marginBottom: 4 }}>
        {me?.email || "No Email"}
      </div>
      <div style={{ fontSize: 13, color: '#666', marginBottom: 8 }}>
        Role: {me?.role || "Member"}
      </div>

      <div style={{ width: '100%', textAlign: 'left', marginTop: 8 }}>
        <strong>Events Participated</strong>
        {activities?.length > 0 ? (
          activities.map(ev => (
            <div key={ev.id} style={{ padding: 6, borderBottom: '1px solid #f0f0f0' }}>
              {ev.title} — {ev.type} {/* type: 'Volunteering' or 'Donation' */}
            </div>
          ))
        ) : (
          <div style={{ fontSize: 12, color: '#888' }}>No events participated yet.</div>
        )}
      </div>
    </div>
  )}
</div>
